--- /dev/null
+++ b/durability.go
@@ -0,0 +1,484 @@
+// Copyright 2026 The LevelDB-Go and Pebble Authors. All rights reserved. Use
+// of this source code is governed by a BSD-style license that can be found in
+// the LICENSE file.
+
+package pebble
+
+import (
+	"container/heap"
+	"context"
+	"reflect"
+	"sync"
+	"time"
+
+	"github.com/cockroachdb/errors"
+	"github.com/cockroachdb/pebble/internal/base"
+)
+
+// ErrDurabilityJobExpired is returned (wrapped) by WaitForJobDurability when
+// the requested job ID was issued but has fallen out of the bounded retention
+// window of recently completed durability jobs.
+var ErrDurabilityJobExpired = errors.New("pebble: durability job expired")
+
+// ErrDurabilityJobUnknown is returned (wrapped) by WaitForJobDurability when
+// the requested job ID was never issued by a BatchDurable callback.
+var ErrDurabilityJobUnknown = errors.New("pebble: unknown durability job")
+
+// errDurabilityTooManySubscriptions is delivered on channels returned by
+// DurabilityNotify when the number of outstanding subscriptions exceeds
+// maxDurabilitySubscriptions.
+var errDurabilityTooManySubscriptions = errors.New("pebble: too many outstanding durability subscriptions")
+
+const (
+	// durabilityJobRetention is the number of most recent durability job
+	// results retained for WaitForJobDurability.
+	durabilityJobRetention = 1024
+	// maxDurabilitySubscriptions bounds the number of outstanding (undelivered)
+	// DurabilityNotify subscriptions.
+	maxDurabilitySubscriptions = 1024
+)
+
+// DurabilityStats is a snapshot of the durability tracking state of a DB. See
+// DB.DurabilityStats.
+type DurabilityStats struct {
+	// HighestDurableSeqNum is the highest sequence number that has been made
+	// durable by a successful synced commit since the DB was opened.
+	HighestDurableSeqNum base.SeqNum
+	// FirstErr is the first WAL sync error encountered, if any.
+	FirstErr error
+	// PendingWaiters is the number of goroutines currently blocked in one of
+	// the WaitForDurability* APIs.
+	PendingWaiters int64
+	// TotalDurableCommits is the number of synced commits that successfully
+	// became durable.
+	TotalDurableCommits uint64
+	// TotalFailedCommits is the number of synced commits that failed.
+	TotalFailedCommits uint64
+	// CumulativeSyncDuration is the sum of the WAL sync phase durations of
+	// successful synced commits.
+	CumulativeSyncDuration time.Duration
+	// MaxSyncDuration is the maximum WAL sync phase duration of a successful
+	// synced commit.
+	MaxSyncDuration time.Duration
+}
+
+// noopBatchDurable is the default EventListener.BatchDurable callback
+// installed by EventListener.EnsureDefaults. It is a named function so that
+// it can be distinguished from a user-configured callback.
+func noopBatchDurable(BatchDurableInfo) {}
+
+// isBatchDurableConfigured returns true if f is a user-provided BatchDurable
+// callback (i.e. not nil and not the default no-op).
+func isBatchDurableConfigured(f func(BatchDurableInfo)) bool {
+	return f != nil && reflect.ValueOf(f).Pointer() != reflect.ValueOf(noopBatchDurable).Pointer()
+}
+
+// durabilityWaiter is a registered interest in a sequence number becoming
+// durable. Exactly one value is sent on ch.
+type durabilityWaiter struct {
+	seqNum base.SeqNum
+	ch     chan error
+	// blocking is true for waiters registered by a goroutine blocked in a wait
+	// API (counted in pendingWaiters), and false for DurabilityNotify
+	// subscriptions (counted in numSubscriptions).
+	blocking bool
+	// index is the waiter's position in the heap, or -1 once removed.
+	index int
+}
+
+type durabilityWaiterHeap []*durabilityWaiter
+
+func (h durabilityWaiterHeap) Len() int           { return len(h) }
+func (h durabilityWaiterHeap) Less(i, j int) bool { return h[i].seqNum < h[j].seqNum }
+func (h durabilityWaiterHeap) Swap(i, j int) {
+	h[i], h[j] = h[j], h[i]
+	h[i].index = i
+	h[j].index = j
+}
+func (h *durabilityWaiterHeap) Push(x any) {
+	w := x.(*durabilityWaiter)
+	w.index = len(*h)
+	*h = append(*h, w)
+}
+func (h *durabilityWaiterHeap) Pop() any {
+	old := *h
+	n := len(old)
+	w := old[n-1]
+	old[n-1] = nil
+	w.index = -1
+	*h = old[:n-1]
+	return w
+}
+
+type durabilityJob struct {
+	id  int
+	err error
+}
+
+// durabilityTracker tracks which sequence numbers have been made durable by
+// synced commits, and lets callers wait on durability.
+//
+// Since the WAL is written sequentially in sequence number order, the
+// successful sync of a batch implies that every sequence number below the end
+// of that batch is durable, including those of earlier unsynced commits.
+type durabilityTracker struct {
+	disableWAL bool
+
+	mu struct {
+		sync.Mutex
+		// floor is the log sequence number at the time the DB was opened. All
+		// sequence numbers below it were durable at open.
+		floor base.SeqNum
+		// highest is the highest sequence number made durable since open.
+		highest base.SeqNum
+		// firstErr is the first sync error encountered.
+		firstErr error
+		// closedErr is set when the DB is closed.
+		closedErr error
+
+		waiters          durabilityWaiterHeap
+		pendingWaiters   int64
+		numSubscriptions int
+
+		// lastJobID is the most recently issued job ID. Job IDs are issued
+		// consecutively starting at 1.
+		lastJobID int
+		jobs      [durabilityJobRetention]durabilityJob
+
+		totalDurable uint64
+		totalFailed  uint64
+		cumSync      time.Duration
+		maxSync      time.Duration
+
+		// Metrics accumulated only when a BatchDurable callback is configured.
+		metricsCount    uint64
+		metricsDuration time.Duration
+	}
+}
+
+func newDurabilityTracker(disableWAL bool) *durabilityTracker {
+	return &durabilityTracker{disableWAL: disableWAL}
+}
+
+func (t *durabilityTracker) setFloor(seqNum base.SeqNum) {
+	t.mu.Lock()
+	defer t.mu.Unlock()
+	t.mu.floor = seqNum
+}
+
+// errLocked returns the error that takes precedence over any other outcome of
+// a wait, if any.
+func (t *durabilityTracker) errLocked() error {
+	if t.mu.firstErr != nil {
+		return t.mu.firstErr
+	}
+	return t.mu.closedErr
+}
+
+func (t *durabilityTracker) satisfiedLocked(seqNum base.SeqNum) bool {
+	return seqNum == 0 || seqNum < t.mu.floor || seqNum <= t.mu.highest
+}
+
+// deliverLocked sends err to w and releases its accounting.
+func (t *durabilityTracker) deliverLocked(w *durabilityWaiter, err error) {
+	if w.blocking {
+		t.mu.pendingWaiters--
+	} else {
+		t.mu.numSubscriptions--
+	}
+	w.ch <- err
+}
+
+// failAllLocked delivers err to every registered waiter.
+func (t *durabilityTracker) failAllLocked(err error) {
+	for _, w := range t.mu.waiters {
+		w.index = -1
+		t.deliverLocked(w, err)
+	}
+	t.mu.waiters = nil
+}
+
+// complete records the outcome of a synced commit of the batch occupying
+// sequence numbers [seqNum, seqNum+count). It returns the job ID assigned to
+// the commit.
+func (t *durabilityTracker) complete(
+	seqNum base.SeqNum, count uint32, err error, syncDur time.Duration, recordMetrics bool,
+) int {
+	t.mu.Lock()
+	defer t.mu.Unlock()
+
+	t.mu.lastJobID++
+	jobID := t.mu.lastJobID
+	t.mu.jobs[jobID%durabilityJobRetention] = durabilityJob{id: jobID, err: err}
+
+	if err != nil {
+		t.mu.totalFailed++
+		if t.mu.firstErr == nil {
+			t.mu.firstErr = err
+		}
+		t.failAllLocked(t.mu.firstErr)
+		return jobID
+	}
+
+	t.mu.totalDurable++
+	t.mu.cumSync += syncDur
+	t.mu.maxSync = max(t.mu.maxSync, syncDur)
+	if recordMetrics {
+		t.mu.metricsCount++
+		t.mu.metricsDuration += syncDur
+	}
+	if count > 0 {
+		if last := seqNum + base.SeqNum(count) - 1; last > t.mu.highest {
+			t.mu.highest = last
+		}
+	}
+	if t.mu.firstErr != nil {
+		// Waiters were already failed when the error was latched.
+		return jobID
+	}
+	for len(t.mu.waiters) > 0 && t.satisfiedLocked(t.mu.waiters[0].seqNum) {
+		t.deliverLocked(heap.Pop(&t.mu.waiters).(*durabilityWaiter), nil)
+	}
+	return jobID
+}
+
+// close fails all outstanding waiters and causes future waits to fail.
+func (t *durabilityTracker) close(err error) {
+	t.mu.Lock()
+	defer t.mu.Unlock()
+	if t.mu.closedErr == nil {
+		t.mu.closedErr = err
+	}
+	t.failAllLocked(t.errLocked())
+}
+
+// wait blocks until seqNum is durable, an error is latched, the DB is closed,
+// or ctx is done. Latched and close errors take precedence over context
+// cancellation.
+func (t *durabilityTracker) wait(ctx context.Context, seqNum base.SeqNum) error {
+	if t.disableWAL {
+		return nil
+	}
+	t.mu.Lock()
+	if err := t.errLocked(); err != nil {
+		t.mu.Unlock()
+		return err
+	}
+	if t.satisfiedLocked(seqNum) {
+		t.mu.Unlock()
+		return nil
+	}
+	if err := ctx.Err(); err != nil {
+		t.mu.Unlock()
+		return err
+	}
+	w := &durabilityWaiter{seqNum: seqNum, ch: make(chan error, 1), blocking: true}
+	heap.Push(&t.mu.waiters, w)
+	t.mu.pendingWaiters++
+	t.mu.Unlock()
+
+	select {
+	case err := <-w.ch:
+		return err
+	case <-ctx.Done():
+	}
+
+	t.mu.Lock()
+	defer t.mu.Unlock()
+	if w.index >= 0 {
+		heap.Remove(&t.mu.waiters, w.index)
+		t.mu.pendingWaiters--
+	}
+	if err := t.errLocked(); err != nil {
+		return err
+	}
+	select {
+	case err := <-w.ch:
+		return err
+	default:
+		return ctx.Err()
+	}
+}
+
+// notify returns a buffered channel on which exactly one value will be sent
+// when seqNum is durable (nil) or durability fails (non-nil).
+func (t *durabilityTracker) notify(seqNum base.SeqNum) <-chan error {
+	ch := make(chan error, 1)
+	if t.disableWAL {
+		ch <- nil
+		return ch
+	}
+	t.mu.Lock()
+	defer t.mu.Unlock()
+	if err := t.errLocked(); err != nil {
+		ch <- err
+		return ch
+	}
+	if t.satisfiedLocked(seqNum) {
+		ch <- nil
+		return ch
+	}
+	if t.mu.numSubscriptions >= maxDurabilitySubscriptions {
+		ch <- errDurabilityTooManySubscriptions
+		return ch
+	}
+	t.mu.numSubscriptions++
+	heap.Push(&t.mu.waiters, &durabilityWaiter{seqNum: seqNum, ch: ch})
+	return ch
+}
+
+// waitJob returns the outcome of the durability job with the given ID.
+// Durability jobs are complete by the time their ID is observable through the
+// BatchDurable callback, so this never blocks.
+func (t *durabilityTracker) waitJob(_ context.Context, jobID int) error {
+	if t.disableWAL {
+		return nil
+	}
+	t.mu.Lock()
+	defer t.mu.Unlock()
+	if jobID <= 0 || jobID > t.mu.lastJobID {
+		return errors.Wrapf(ErrDurabilityJobUnknown, "job %d", errors.Safe(jobID))
+	}
+	if t.mu.lastJobID-jobID >= durabilityJobRetention {
+		return errors.Wrapf(ErrDurabilityJobExpired, "job %d", errors.Safe(jobID))
+	}
+	if err := t.errLocked(); err != nil {
+		return err
+	}
+	job := t.mu.jobs[jobID%durabilityJobRetention]
+	if job.id != jobID {
+		return errors.AssertionFailedf("pebble: durability job %d not found (found %d)",
+			errors.Safe(jobID), errors.Safe(job.id))
+	}
+	return job.err
+}
+
+func (t *durabilityTracker) state() (base.SeqNum, error) {
+	t.mu.Lock()
+	defer t.mu.Unlock()
+	return t.mu.highest, t.mu.firstErr
+}
+
+func (t *durabilityTracker) stats() DurabilityStats {
+	t.mu.Lock()
+	defer t.mu.Unlock()
+	return DurabilityStats{
+		HighestDurableSeqNum:   t.mu.highest,
+		FirstErr:               t.mu.firstErr,
+		PendingWaiters:         t.mu.pendingWaiters,
+		TotalDurableCommits:    t.mu.totalDurable,
+		TotalFailedCommits:     t.mu.totalFailed,
+		CumulativeSyncDuration: t.mu.cumSync,
+		MaxSyncDuration:        t.mu.maxSync,
+	}
+}
+
+func (t *durabilityTracker) metrics() (uint64, time.Duration) {
+	t.mu.Lock()
+	defer t.mu.Unlock()
+	return t.mu.metricsCount, t.mu.metricsDuration
+}
+
+// positiveDuration clamps a measured duration to be at least 1ns so that
+// durations measured with a coarse clock are still reported as positive.
+func positiveDuration(d time.Duration) time.Duration {
+	return max(d, time.Nanosecond)
+}
+
+// onBatchDurable records the outcome of a synced commit of b and invokes the
+// BatchDurable event listener.
+func (d *DB) onBatchDurable(b *Batch, err error, syncDur time.Duration) {
+	listener := d.opts.EventListener.BatchDurable
+	configured := isBatchDurableConfigured(listener)
+	applyDur := b.durableApplyDuration
+	if err == nil {
+		applyDur = positiveDuration(applyDur)
+		syncDur = positiveDuration(syncDur)
+	}
+	jobID := d.durability.complete(b.durableSeqNum, b.durableKeyCount, err, syncDur, configured)
+	if listener != nil {
+		listener(BatchDurableInfo{
+			JobID:         jobID,
+			SeqNum:        b.durableSeqNum,
+			Err:           err,
+			ApplyDuration: applyDur,
+			SyncDuration:  syncDur,
+			CorrelationID: b.durableCorrelationID,
+			BatchSize:     b.durableBatchSize,
+			KeyCount:      b.durableKeyCount,
+		})
+	}
+}
+
+// WaitForDurability blocks until the given sequence number is durable. A
+// sequence number written by an unsynced commit becomes durable once a later
+// synced commit completes. Zero is always considered durable. Returns an error
+// if a WAL sync failed or the DB is closed. If the WAL is disabled, returns nil
+// immediately.
+func (d *DB) WaitForDurability(seqNum base.SeqNum) error {
+	return d.durability.wait(context.Background(), seqNum)
+}
+
+// WaitForDurabilityContext is like WaitForDurability, but also returns when
+// ctx is done. Durability and close errors take precedence over context
+// errors.
+func (d *DB) WaitForDurabilityContext(ctx context.Context, seqNum base.SeqNum) error {
+	return d.durability.wait(ctx, seqNum)
+}
+
+// WaitForDurabilityBatch blocks until every sequence number in seqNums is
+// durable. Returns nil for a nil or empty slice.
+func (d *DB) WaitForDurabilityBatch(seqNums []base.SeqNum) error {
+	return d.WaitForDurabilityBatchContext(context.Background(), seqNums)
+}
+
+// WaitForDurabilityBatchContext is like WaitForDurabilityBatch, but also
+// returns when ctx is done. Durability and close errors take precedence over
+// context errors.
+func (d *DB) WaitForDurabilityBatchContext(ctx context.Context, seqNums []base.SeqNum) error {
+	if len(seqNums) == 0 {
+		return nil
+	}
+	// Durability is monotonic, so waiting for the largest sequence number
+	// suffices.
+	var maxSeqNum base.SeqNum
+	for _, s := range seqNums {
+		maxSeqNum = max(maxSeqNum, s)
+	}
+	return d.durability.wait(ctx, maxSeqNum)
+}
+
+// WaitForJobDurability waits for the synced commit identified by the JobID of
+// a BatchDurableInfo, returning the commit's outcome. Only a bounded window of
+// recent jobs is retained; older jobs return an error wrapping
+// ErrDurabilityJobExpired. Job IDs that were never issued (including zero)
+// return an error wrapping ErrDurabilityJobUnknown.
+func (d *DB) WaitForJobDurability(jobID int) error {
+	return d.durability.waitJob(context.Background(), jobID)
+}
+
+// WaitForJobDurabilityContext is like WaitForJobDurability, but accepts a
+// context.
+func (d *DB) WaitForJobDurabilityContext(ctx context.Context, jobID int) error {
+	return d.durability.waitJob(ctx, jobID)
+}
+
+// DurableState returns the highest sequence number made durable since the DB
+// was opened, and the first WAL sync error encountered, if any.
+func (d *DB) DurableState() (base.SeqNum, error) {
+	return d.durability.state()
+}
+
+// DurabilityNotify returns a channel that receives exactly one value: nil once
+// seqNum is durable, or a non-nil error if a WAL sync fails or the DB is
+// closed. The channel is buffered, so the receiver may read it at any time.
+// The number of outstanding subscriptions is bounded; beyond the bound, the
+// returned channel immediately holds a non-nil error.
+func (d *DB) DurabilityNotify(seqNum base.SeqNum) <-chan error {
+	return d.durability.notify(seqNum)
+}
+
+// DurabilityStats returns a snapshot of the DB's durability tracking state.
+func (d *DB) DurabilityStats() DurabilityStats {
+	return d.durability.stats()
+}
